package com.gk.jobhelper.service;
import com.gk.jobhelper.common.*;import com.gk.jobhelper.dto.*;import com.gk.jobhelper.mapper.RecruitmentAttachmentMapper;import com.gk.jobhelper.mapper.RecruitmentNoticeMapper;import org.springframework.stereotype.Service;import java.time.LocalDateTime;import java.util.*;
@Service public class RecruitmentNoticeService {private final RecruitmentNoticeMapper mapper;private final RecruitmentAttachmentMapper attachmentMapper;private static final Set<String> STATUS=new HashSet<>(Arrays.asList("NEW","INTERESTED","FOLLOWING","IGNORED"));public RecruitmentNoticeService(RecruitmentNoticeMapper m,RecruitmentAttachmentMapper a){mapper=m;attachmentMapper=a;}public PageVO<RecruitmentNoticeVO> page(String status,String sourceCode,String keyword,int page,int size){if(status!=null&&!status.isEmpty()&&!STATUS.contains(status))throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"无效公告状态");int p=Math.max(1,page),s=Math.min(100,Math.max(1,size));String k=keyword==null||keyword.trim().isEmpty()?null:"%"+keyword.trim()+"%";return new PageVO<>(mapper.count(status,sourceCode,k),p,s,mapper.selectPage(status,sourceCode,k,(p-1)*s,s));}public RecruitmentNoticeVO detail(Long id){RecruitmentNoticeVO n=mapper.selectDetail(id);if(n==null)throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"招聘公告不存在: "+id);n.setAttachments(attachmentMapper.selectByNoticeId(id));return n;}public void updateStatus(Long id,String status){detail(id);if(!STATUS.contains(status))throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"无效公告状态");mapper.updateStatus(id,status,LocalDateTime.now());}public void view(Long id){detail(id);mapper.markViewed(id,LocalDateTime.now());}}
